base =
    from(bucket: "${bucket}")
        |> range(
            start: v.timeRangeStart,
            stop: v.timeRangeStop
        )

        |> filter(fn: (r) =>
            r["_measurement"] == "${meas}" and
            (
                r["_field"] == "status" or
                r["_field"] == "serialboard_id" or
                r["_field"] == "protectboard_id"
            )
        )

        |> filter(fn: (r) =>
            r["return_code"] =~ /^${return_code:regex}$/
        )

        // Build slot key
        |> map(fn: (r) => ({
            r with
            slot_key:
                string(v: r.storehouse_id) + "|" +
                string(v: r.pallet_position) + "|" +
                string(v: r.position_id)
        }))

        // Filter selected physical slots
        |> filter(fn: (r) =>
            r.slot_key =~ /^${slot_filter:regex}$/
        )

        // Convert fields into columns
        |> pivot(
            rowKey: [
                "_time",
                "storehouse_id",
                "pallet_position",
                "position_id",
                "return_code"
            ],
            columnKey: ["_field"],
            valueColumn: "_value"
        )

        // Keep only complete records
        |> filter(fn: (r) =>
            exists r.status and
            exists r.serialboard_id and
            exists r.protectboard_id
        )

        // Build SerialBoard + ProtectBoard pair
        |> map(fn: (r) => ({
            r with
            board_pair:
                string(v: r.serialboard_id) +
                " | " +
                string(v: r.protectboard_id)
        }))

        // Keep selected board pair
        |> filter(fn: (r) =>
            r.board_pair == "${board_pair}"
        )

        // Merge all records for the selected board pair
        |> group()

        // Latest record first
        |> sort(
            columns: ["_time"],
            desc: true
        )

        // Keep only the latest status
        |> limit(n: 1)


uvp =
    base
        |> map(fn: (r) => ({
            _field: "UVP",
            _value: int(v: r.status / 32768) % 2
        }))


ovp =
    base
        |> map(fn: (r) => ({
            _field: "OVP",
            _value: int(v: r.status / 65536) % 2
        }))


ocp =
    base
        |> map(fn: (r) => ({
            _field: "OCP",
            _value: int(v: r.status / 131072) % 2
        }))


ovs =
