    )

    // Build slot key
    |> map(fn: (r) => ({
        r with
        slot_key:
            string(v: r.storehouse_id) + "|" +
            string(v: r.pallet_position) + "|" +
            string(v: r.position_id)
    }))

    // Filter selected physical slots
    |> filter(fn: (r) =>
        r.slot_key =~ /^${slot_filter:regex}$/
    )

    // Keep only L / R pallet positions
    |> filter(fn: (r) =>
        r["pallet_position"] == "L" or
        r["pallet_position"] == "R"
    )

    // Keep required fields and timestamp
    |> map(fn: (r) => ({
        _time: r._time,
        serialboard_id: string(v: r._value),
        storehouse_id: r.storehouse_id,
        pallet_position: r.pallet_position,
        position_id: r.position_id
    }))

    // One group per SerialBoard ID
    |> group(columns: ["serialboard_id"])

    // Latest record first
    |> sort(
        columns: ["_time"],
        desc: true
    )

    // Keep only latest location for each SerialBoard ID
    |> limit(n: 1)

    // Build location
    |> map(fn: (r) => ({
        serialboard_id: r.serialboard_id,
        location:
            "R" +
            string(v: r.storehouse_id) +
            "_" +
            string(v: r.pallet_position)
    }))

    // Merge all SerialBoard IDs
    |> group()

    // Sort SerialBoard ID from small to large
    |> sort(
        columns: ["serialboard_id"],
        desc: false
    )

    // Final Grafana output
    |> map(fn: (r) => ({
        _field: r.serialboard_id,
        _value: r.location
    }))

