serialData =
    from(bucket: "${bucket}")
        |> range(
            start: v.timeRangeStart,
            stop: v.timeRangeStop
        )
        |> filter(fn: (r) =>
            r["_measurement"] == "${meas}" and
            r["_field"] == "serialboard_id"
        )
        |> filter(fn: (r) =>
            r["return_code"] =~ /^${return_code:regex}$/
        )
        |> map(fn: (r) => ({
            r with
            slot_key:
                string(v: r.storehouse_id) + "|" +
                string(v: r.pallet_position) + "|" +
                string(v: r.position_id)
        }))
        |> filter(fn: (r) =>
            r.slot_key =~ /^${slot_filter:regex}$/
        )

        // Get latest SerialBoard ID for each slot
        |> group(columns: [
            "storehouse_id",
            "pallet_position",
            "position_id"
        ])
        |> sort(
            columns: ["_time"],
            desc: true
        )
        |> limit(n: 1)

        // Keep timestamp for final SerialBoard deduplication
        |> map(fn: (r) => ({
            serial_time: r._time,
            serialboard_id: string(v: r._value),
            storehouse_id: r.storehouse_id,
            pallet_position: r.pallet_position,
            position_id: r.position_id
        }))
        |> group()


currentData =
    from(bucket: "${bucket}")
        |> range(
            start: v.timeRangeStart,
            stop: v.timeRangeStop
        )
        |> filter(fn: (r) =>
            r["_measurement"] == "${meas}" and
            r["_field"] == "error_value_curr"
        )
        |> filter(fn: (r) =>
            r["return_code"] =~ /^${return_code:regex}$/
        )
        |> map(fn: (r) => ({
            r with
            slot_key:
                string(v: r.storehouse_id) + "|" +
                string(v: r.pallet_position) + "|" +
                string(v: r.position_id)
        }))
        |> filter(fn: (r) =>
