            position_id: r.position_id
        }))
        |> group()


codeData =
    from(bucket: "${bucket}")
        |> range(
            start: v.timeRangeStart,
            stop: v.timeRangeStop
        )
        |> filter(fn: (r) =>
            r["_measurement"] == "${meas}" and
            r["_field"] == "error_code_curr"
        )
        |> filter(fn: (r) =>
            r["return_code"] =~ /^${return_code:regex}$/
        )
        |> map(fn: (r) => ({
            r with
            slot_key:
                string(v: r.storehouse_id) + "|" +
                string(v: r.pallet_position) + "|" +
                string(v: r.position_id)
        }))
        |> filter(fn: (r) =>
            r.slot_key =~ /^${slot_filter:regex}$/
        )

        // Get latest error code for each slot
        |> group(columns: [
            "storehouse_id",
            "pallet_position",
            "position_id"
        ])
        |> sort(
            columns: ["_time"],
            desc: true
        )
        |> limit(n: 1)

        |> map(fn: (r) => ({
            error_code_curr: string(v: r._value),
            storehouse_id: r.storehouse_id,
            pallet_position: r.pallet_position,
            position_id: r.position_id
        }))
        |> group()


// Join error value and error code
currentWithCode =
    join(
        tables: {
            curr: currentData,
            code: codeData
        },
        on: [
            "storehouse_id",
            "pallet_position",
            "position_id"
        ],
        method: "inner"
    )


// Join SerialBoard ID
result =
    join(
        tables: {
            data: currentWithCode,
            serial: serialData
        },
        on: [
            "storehouse_id",
            "pallet_position",
            "position_id"
        ],
        method: "inner"
    )

        |> map(fn: (r) => ({
            _time: r.serial_time,
            serialboard_id: r.serialboard_id,

            _value:
                if
                    r.error_code_curr == "OC" or
                    r.error_code_curr == "UC"
                then
                    string(v: r.error_value_curr) + " mA"
                else
                    string(v: r.error_value_curr)
        }))


// Each SerialBoard ID keeps only its latest record
result
    |> group(columns: ["serialboard_id"])

    |> sort(
        columns: ["_time"],
        desc: true
    )

    |> limit(n: 1)

    // Final Grafana output
    |> map(fn: (r) => ({
        serialboard_id: r.serialboard_id,
        _value: r._value
    }))

